"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { Heart, HeartCrack, ShoppingCart, Trash2 } from "lucide-react";

interface Product {
  product_id: number;
  name: string;
  price: string;
  image_url: string;
  stock: number;
}

export default function WishlistPage() {
  const [wishlist, setWishlist] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);

  const fetchWishlist = async () => {
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        setLoading(false);
        return;
      }

      const res = await fetch("http://localhost:5000/wishlist", {
        headers: { token }
      });
      const data = await res.json();
      setWishlist(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchWishlist();
  }, []);

  const removeFromWishlist = async (productId: number) => {
    try {
      const token = localStorage.getItem("token");
      await fetch("http://localhost:5000/wishlist/toggle", {
        method: "POST",
        headers: { "Content-Type": "application/json", token: token || "" },
        body: JSON.stringify({ product_id: productId })
      });
      // Махаме го веднага от екрана
      setWishlist(wishlist.filter(p => p.product_id !== productId));
    } catch (err) {
      console.error(err);
    }
  };

  if (loading) return <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center text-[#ff6b00] uppercase font-bold tracking-widest animate-pulse">Зареждане...</div>;

  return (
    <div className="min-h-screen bg-[#0a0a0a] text-white p-6 md:p-12 font-sans relative overflow-hidden">
        {/* Декорация */}
        <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-red-500/10 rounded-full blur-[120px] pointer-events-none"></div>

        <div className="max-w-6xl mx-auto relative z-10">
            <div className="flex items-center gap-4 mb-10 border-b border-gray-800 pb-6">
                <div className="p-4 bg-red-500/10 rounded-xl text-red-500 border border-red-500/20 shadow-[0_0_20px_rgba(239,68,68,0.2)]">
                    <Heart size={32} className="fill-red-500" />
                </div>
                <div>
                    <h1 className="text-4xl font-black uppercase tracking-tighter italic">
                        Моите <span className="text-red-500">Любими</span>
                    </h1>
                    <p className="text-gray-400 text-xs tracking-widest uppercase mt-1">Запазени продукти за по-късно</p>
                </div>
            </div>

            {wishlist.length === 0 ? (
                <div className="bg-[#18181b] border border-gray-800 rounded-2xl p-16 flex flex-col items-center text-center shadow-2xl">
                    <HeartCrack size={64} className="text-gray-700 mb-6" />
                    <h2 className="text-2xl font-bold uppercase mb-2">Списъкът е празен</h2>
                    <p className="text-gray-500 mb-8 max-w-md text-sm">Все още не сте добавили нищо в любими. Разгледайте каталога и запазете техниките, които ви харесват.</p>
                    <Link href="/shop">
                        <button className="bg-gradient-to-r from-[#ff6b00] to-[#e65c00] hover:from-[#e65c00] hover:to-[#cc5200] text-black font-black uppercase px-8 py-4 rounded-xl text-xs tracking-widest transition-all shadow-[0_5px_15px_rgba(255,107,0,0.3)] transform hover:-translate-y-1">
                            Към Каталога
                        </button>
                    </Link>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {wishlist.map((product) => (
                        <div key={product.product_id} className="bg-[#18181b] border border-gray-800 rounded-2xl overflow-hidden group hover:border-[#ff6b00]/50 transition-colors shadow-xl flex flex-col">
                            <Link href={`/shop/${product.product_id}`} className="relative h-64 overflow-hidden bg-white p-4 flex items-center justify-center">
                                <img 
                                    src={product.image_url} 
                                    alt={product.name} 
                                    className="w-full h-full object-contain group-hover:scale-110 transition-transform duration-500"
                                />
                                {product.stock === 0 && (
                                    <div className="absolute inset-0 bg-black/60 flex items-center justify-center backdrop-blur-[2px]">
                                        <span className="bg-red-600 text-white font-black uppercase text-xs tracking-widest px-4 py-2 rounded transform -rotate-12 shadow-2xl">
                                            Изчерпан
                                        </span>
                                    </div>
                                )}
                            </Link>

                            <div className="p-6 flex flex-col flex-grow">
                                <h3 className="font-bold text-lg leading-tight mb-2 uppercase line-clamp-2">{product.name}</h3>
                                <p className="text-[#ff6b00] font-black text-xl mb-6 mt-auto">{Number(product.price).toFixed(2)} €</p>
                                
                                <div className="flex gap-2">
                                    <Link href={`/shop/${product.product_id}`} className="flex-grow">
                                        <button className="w-full bg-[#0a0a0a] border border-[#333] hover:border-[#ff6b00] hover:text-[#ff6b00] text-white font-bold uppercase text-[10px] tracking-widest py-3 rounded-lg transition-colors flex items-center justify-center gap-2">
                                            <ShoppingCart size={14} /> Виж
                                        </button>
                                    </Link>
                                    <button 
                                        onClick={() => removeFromWishlist(product.product_id)}
                                        className="bg-red-500/10 hover:bg-red-500 border border-red-500/20 hover:border-red-500 text-red-500 hover:text-white p-3 rounded-lg transition-all"
                                        title="Премахни от любими"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    </div>
  );
}